import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1785480634000}`),a={name:`guide/introduction.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><p>BullMQ is based in 4 classes that together can be used to resolve many different problems. These classes are <a href="https://docs.bullmq.io/api/classes/v6.Queue.html" target="_blank" rel="noreferrer"><em><strong>Queue</strong></em></a>, <a href="https://docs.bullmq.io/api/classes/v6.Worker.html" target="_blank" rel="noreferrer"><em><strong>Worker</strong></em></a>, <a href="https://docs.bullmq.io/api/classes/v6.QueueEvents.html" target="_blank" rel="noreferrer"><em><strong>QueueEvents</strong></em></a> and <a href="https://docs.bullmq.io/api/classes/v6.FlowProducer.html" target="_blank" rel="noreferrer"><em><strong>FlowProducer</strong></em></a>.</p><p>The first class you should know about is the <em>Queue</em> class. This class represents a queue and can be used for adding <em><strong>jobs</strong></em> to the queue as well as some other basic manipulation such as pausing, cleaning or getting data from the queue.</p><p>Jobs in BullMQ are basically a user created data structure that can be stored in the queue. Jobs are processed by <em><strong>workers</strong></em>. A <em>Worker</em> is the second class you should be aware about. Workers are instances capable of processing jobs. You can have many workers, either running in the same Node.js process, or in separate processes as well as in different machines. They will all consume jobs from the queue and mark the jobs as completed or failed.</p>`,4)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default}